#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Metadata-Aware RAG System
=========================

A self-contained Retrieval-Augmented Generation (RAG) system that:

  1. Chunks long documents while preserving rich metadata (category, tags,
     date, source, author, priority, ...).
  2. Indexes chunks with two complementary retrievers:
       * TF-IDF cosine similarity (term-overlap ranking)
       * BM25 (sparse lexical ranking)
  3. Filters candidate chunks by metadata *before* ranking, supporting
     equality, membership, substring, regex, existence, and numeric/date
     range operators (e.g. {"date": {"$gte": "2024-06-01"}}).
  4. Ranks candidates with a weighted hybrid score plus configurable
     metadata-driven boosts (priority mapping, recency half-life, custom
     field boosters).
  5. Reranks for diversity with Maximal Marginal Relevance (MMR).
  6. Generates grounded, cited extractive answers from retrieved context.

Pure Python standard library, so it runs anywhere. The design maps directly
onto production patterns from the RAG playbook: swap the vectorizer for real
embeddings (OpenAI text-embedding-ada-002, bge, ...), swap the in-memory store
for a vector database (Chroma, Pinecone, Weaviate, Qdrant), and swap the
extractive generator for an LLM grounded with a contextual prompt.
"""

from __future__ import annotations

import hashlib
import math
import re
from collections import Counter
from datetime import datetime
from typing import Any, Callable, Dict, List, Optional, Tuple

# ---------------------------------------------------------------------------
# Text utilities
# ---------------------------------------------------------------------------

TOKEN_RE = re.compile(r"[a-z0-9]+", re.IGNORECASE)
SENTENCE_RE = re.compile(r"(?<=[.!?])\s+|\n+")


def tokenize(text: str) -> List[str]:
    """Lowercased alphanumeric tokens."""
    return [t.lower() for t in TOKEN_RE.findall(text or "")]


def parse_date(value: Any) -> Optional[datetime]:
    """Parse ISO-style dates/datetimes (also tolerates 'Z' suffix)."""
    try:
        s = str(value).strip().replace("Z", "+00:00")
        return datetime.fromisoformat(s)
    except (TypeError, ValueError):
        return None


def parse_number(value: Any) -> Optional[float]:
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


# ---------------------------------------------------------------------------
# Chunking (metadata is attached later by the RAG system)
# ---------------------------------------------------------------------------

class RecursiveChunker:
    """Split long text into overlapping chunks using largest separators first."""

    def __init__(self, chunk_size: int = 700, overlap: int = 90):
        assert chunk_size > 0 and 0 <= overlap < chunk_size
        self.chunk_size = chunk_size
        self.overlap = overlap

    def split(self, text: str) -> List[str]:
        text = (text or "").strip()
        if not text:
            return []
        base = self._split(text, ["\n\n", "\n", ". ", " ", ""])
        base = [c.strip() for c in base if c.strip()]
        if len(base) <= 1:
            return base
        out = [base[0]]
        for i in range(1, len(base)):
            tail = base[i - 1][-self.overlap:] if self.overlap else ""
            out.append((tail + base[i]).strip())
        return out

    def _split(self, text: str, separators: List[str]) -> List[str]:
        if len(text) <= self.chunk_size:
            return [text]
        if not separators:
            return [text[i:i + self.chunk_size] for i in range(0, len(text), self.chunk_size)]
        sep = separators[0]
        if sep not in text:
            return self._split(text, separators[1:])
        parts = text.split(sep)
        chunks: List[str] = []
        current = ""
        for part in parts:
            piece = part + sep
            if current and len(current) + len(piece) > self.chunk_size:
                chunks.append(current)
                current = piece
            else:
                current += piece
        if current:
            chunks.append(current)
        result: List[str] = []
        for c in chunks:
            if len(c) > self.chunk_size:
                result.extend(self._split(c, separators[1:]))
            else:
                result.append(c)
        return result


# ---------------------------------------------------------------------------
# TF-IDF retriever (cosine similarity over normalized tf-idf vectors)
# ---------------------------------------------------------------------------

class TfIdfIndex:
    """Lazy, dependency-free TF-IDF index with cosine scoring."""

    def __init__(self) -> None:
        self.counts: List[Counter] = []
        self.vectors: List[Dict[str, float]] = []
        self.idf: Dict[str, float] = {}
        self.n_docs = 0

    def fit(self, texts: List[str]) -> "TfIdfIndex":
        self.counts = [Counter(tokenize(t)) for t in texts]
        self.n_docs = len(texts)
        df: Counter = Counter()
        for c in self.counts:
            df.update(c.keys())
        # Smooth idf so rare terms are weighted higher.
        self.idf = {term: math.log((self.n_docs + 1.0) / (n + 1.0)) + 1.0
                    for term, n in df.items()}
        self.vectors = []
        for c in self.counts:
            vec: Dict[str, float] = {}
            norm = 0.0
            for term, freq in c.items():
                w = (1.0 + math.log(freq)) * self.idf.get(term, 0.0)
                vec[term] = w
                norm += w * w
            norm = math.sqrt(norm) or 1.0
            self.vectors.append({t: w / norm for t, w in vec.items()})
        return self

    def query_vector(self, query_tokens: List[str]) -> Dict[str, float]:
        counts = Counter(query_tokens)
        vec: Dict[str, float] = {}
        norm = 0.0
        for term, freq in counts.items():
            idf = self.idf.get(term)
            if idf is None:  # term never seen in corpus -> contributes nothing
                continue
            w = (1.0 + math.log(freq)) * idf
            vec[term] = w
            norm += w * w
        norm = math.sqrt(norm) or 1.0
        return {t: w / norm for t, w in vec.items()}

    @staticmethod
    def cosine(a: Dict[str, float], b: Dict[str, float]) -> float:
        total = 0.0
        for term, w in a.items():
            bw = b.get(term)
            if bw:
                total += w * bw
        return total

    def score_all(self, query_tokens: List[str], indices: List[int]) -> Dict[int, float]:
        qvec = self.query_vector(query_tokens)
        return {i: self.cosine(qvec, self.vectors[i]) for i in indices}


# ---------------------------------------------------------------------------
# BM25 retriever (sparse lexical ranking)
# ---------------------------------------------------------------------------

class BM25:
    """Okapi BM25 with default k1=1.5, b=0.75."""

    def __init__(self, k1: float = 1.5, b: float = 0.75) -> None:
        self.k1 = k1
        self.b = b
        self.freqs: List[Counter] = []
        self.doc_len: List[int] = []
        self.df: Counter = Counter()
        self.avgdl = 0.0
        self.n_docs = 0

    def fit(self, texts: List[str]) -> "BM25":
        self.freqs = [Counter(tokenize(t)) for t in texts]
        self.doc_len = [sum(c.values()) for c in self.freqs]
        self.n_docs = len(texts)
        self.avgdl = (sum(self.doc_len) / self.n_docs) if self.n_docs else 0.0
        self.df = Counter()
        for c in self.freqs:
            self.df.update(c.keys())
        return self

    def score(self, query_tokens: List[str], index: int) -> float:
        dl = self.doc_len[index]
        if dl == 0:
            return 0.0
        freq = self.freqs[index]
        denom_scale = 1.0 - self.b + self.b * (dl / self.avgdl) if self.avgdl else 1.0
        total = 0.0
        for term in set(query_tokens):
            n = self.df.get(term, 0)
            if n == 0:
                continue
            idf = math.log((self.n_docs - n + 0.5) / (n + 0.5) + 1.0)
            tf = freq.get(term, 0)
            total += idf * (tf * (self.k1 + 1.0)) / (tf + self.k1 * denom_scale)
        return total

    def score_all(self, query_tokens: List[str], indices: List[int]) -> Dict[int, float]:
        return {i: self.score(query_tokens, i) for i in indices}


# ---------------------------------------------------------------------------
# Metadata filtering (MongoDB-style operators on document metadata)
# ---------------------------------------------------------------------------

class MetadataFilter:
    """Match a metadata dict against a filter spec.

    Shorthand forms:
        {"category": "security"}                 # equality
        {"category": ["a", "b"]}                 # membership

    Operator forms (dict values keyed by "$op"):
        {"date": {"$gte": "2024-06-01"}}         # range (numeric or date)
        {"tags": {"$contains": "saml"}}          # substring / list membership
        {"title": {"$regex": "^apollo"}}         # regular expression
        {"priority": {"$in": ["high", "medium"]}}
        {"author": {"$exists": True}}
    """

    OPS: Dict[str, str] = {
        "$eq": "eq", "$ne": "ne", "$in": "in", "$nin": "nin",
        "$contains": "contains", "$regex": "regex", "$exists": "exists",
        "$gt": "gt", "$gte": "gte", "$lt": "lt", "$lte": "lte",
    }

    def __init__(self, spec: Optional[Dict[str, Any]] = None) -> None:
        self.spec = spec or {}

    # -- comparison helpers -------------------------------------------------
    @staticmethod
    def _compare(value: Any, expected: Any) -> Optional[int]:
        """Return -1/0/1 when value and expected are comparable, else None."""
        if value is None:
            return None
        n1, n2 = parse_number(value), parse_number(expected)
        if n1 is not None and n2 is not None:
            return -1 if n1 < n2 else (0 if n1 == n2 else 1)
        d1, d2 = parse_date(value), parse_date(expected)
        if d1 is not None and d2 is not None:
            return -1 if d1 < d2 else (0 if d1 == d2 else 1)
        try:
            if value < expected:
                return -1
            if value == expected:
                return 0
            return 1
        except TypeError:
            return None

    # -- operators ----------------------------------------------------------
    def _op_eq(self, v, e): return v == e
    def _op_ne(self, v, e): return v != e
    def _op_in(self, v, e): return v in e
    def _op_nin(self, v, e): return v not in e

    def _op_contains(self, v, e):
        if isinstance(v, str):
            return e in v
        if isinstance(v, (list, tuple, set)):
            if isinstance(e, (list, tuple, set)):
                return bool(set(v) & set(e))
            return e in v
        return False

    def _op_regex(self, v, e):
        return bool(re.search(str(e), str(v))) if v is not None else False

    def _op_exists(self, v, e):
        return (v is not None) == bool(e)

    def _op_gt(self, v, e): c = self._compare(v, e); return c is not None and c > 0
    def _op_gte(self, v, e): c = self._compare(v, e); return c is not None and c >= 0
    def _op_lt(self, v, e): c = self._compare(v, e); return c is not None and c < 0
    def _op_lte(self, v, e): c = self._compare(v, e); return c is not None and c <= 0

    # -- matching -----------------------------------------------------------
    def matches(self, metadata: Dict[str, Any]) -> bool:
        for field, cond in self.spec.items():
            value = metadata.get(field)
            if isinstance(cond, dict):
                for op, expected in cond.items():
                    handler = getattr(self, "_op_" + self.OPS.get(op, ""), None)
                    if handler is None:
                        raise ValueError(f"Unknown metadata operator: {op}")
                    if not handler(value, expected):
                        return False
            elif isinstance(cond, (list, tuple, set)):
                if value not in cond:
                    return False
            elif value != cond:
                return False
        return True


# ---------------------------------------------------------------------------
# Metadata-driven ranking boosts
# ---------------------------------------------------------------------------

class MetadataBoost:
    """Base class: returns a score multiplier from a chunk's metadata."""

    def __call__(self, metadata: Dict[str, Any]) -> float:
        return 1.0


class PriorityBoost(MetadataBoost):
    """Static mapping: field value -> multiplier (e.g. high > medium > low)."""

    def __init__(self, field: str, mapping: Dict[str, float], default: float = 1.0):
        self.field = field
        self.mapping = mapping
        self.default = default

    def __call__(self, metadata: Dict[str, Any]) -> float:
        return self.mapping.get(metadata.get(self.field), self.default)


class RecencyBoost(MetadataBoost):
    """Gentle exponential recency multiplier: 1 + amp * exp(-age/half_life)."""

    def __init__(self, field: str = "date", half_life_days: float = 730.0,
                 amplitude: float = 0.15):
        self.field = field
        self.half_life = half_life_days
        self.amplitude = amplitude

    def __call__(self, metadata: Dict[str, Any]) -> float:
        d = parse_date(metadata.get(self.field))
        if d is None:
            return 1.0
        age_days = max(0.0, (datetime.now() - d).total_seconds() / 86400.0)
        return 1.0 + self.amplitude * math.exp(-age_days / self.half_life)


class CustomFieldBoost(MetadataBoost):
    """Arbitrary callable boost: fn(field_value, full_metadata) -> multiplier."""

    def __init__(self, field: str, fn: Callable[[Any, Dict[str, Any]], float]):
        self.field = field
        self.fn = fn

    def __call__(self, metadata: Dict[str, Any]) -> float:
        return self.fn(metadata.get(self.field), metadata)


# ---------------------------------------------------------------------------
# The RAG system
# ---------------------------------------------------------------------------

class MetadataAwareRAG:
    """End-to-end metadata-filterable, hybrid-ranked RAG system."""

    def __init__(
        self,
        chunk_size: int = 700,
        chunk_overlap: int = 90,
        bm25_k1: float = 1.5,
        bm25_b: float = 0.75,
        boosters: Optional[List[MetadataBoost]] = None,
    ) -> None:
        self.chunker = RecursiveChunker(chunk_size, chunk_overlap)
        self.tfidf = TfIdfIndex()
        self.bm25 = BM25(k1=bm25_k1, b=bm25_b)
        self.chunks: List[Dict[str, Any]] = []
        self.boosters: List[MetadataBoost] = boosters if boosters is not None else [
            PriorityBoost("priority", {"high": 1.15, "medium": 1.0, "low": 0.92}),
            RecencyBoost("date", half_life_days=730.0, amplitude=0.15),
        ]
        self._built = False

    # -- indexing -----------------------------------------------------------
    def add_documents(self, documents: Iterable[Dict[str, Any]]) -> int:
        """Chunk documents, attaching every non-'text' field as metadata."""
        for doc in documents:
            text = (doc.get("text") or "").strip()
            if not text:
                continue
            doc_id = doc.get("doc_id") or hashlib.md5(text.encode()).hexdigest()[:10]
            base_meta = {k: v for k, v in doc.items() if k != "text"}
            base_meta.setdefault("doc_id", doc_id)
            base_meta.setdefault("title", doc_id)
            for i, chunk_text in enumerate(self.chunker.split(text)):
                meta = dict(base_meta)
                meta["chunk_index"] = i
                meta["chunk_id"] = f"{doc_id}::c{i}"
                self.chunks.append({"text": chunk_text, "metadata": meta})
        self._built = False
        return len(self.chunks)

    def build_index(self) -> "MetadataAwareRAG":
        texts = [c["text"] for c in self.chunks]
        self.tfidf.fit(texts)
        self.bm25.fit(texts)
        self._built = True
        return self

    def _ensure_index(self) -> None:
        if not self._built and self.chunks:
            self.build_index()

    # -- ranking helpers ----------------------------------------------------
    @staticmethod
    def _minmax(scores: Dict[int, float], indices: List[int]) -> Dict[int, float]:
        vals = [scores.get(i, 0.0) for i in indices]
        lo, hi = min(vals), max(vals)
        if hi - lo < 1e-12:
            return {i: 0.0 for i in indices}
        return {i: (scores.get(i, lo) - lo) / (hi - lo) for i in indices}

    def _mmr(self, pool: List[int], fused: Dict[int, float],
             lambda_: float, k: int) -> List[int]:
        """Maximal Marginal Relevance: relevance minus similarity to picks."""
        selected: List[int] = []
        remaining = list(pool)
        while len(selected) < k and remaining:
            best_idx, best_val = remaining[0], None
            for i in remaining:
                if selected:
                    diversity = max(
                        self.tfidf.cosine(self.tfidf.vectors[i], self.tfidf.vectors[j])
                        for j in selected
                    )
                else:
                    diversity = 0.0
                val = lambda_ * fused[i] - (1.0 - lambda_) * diversity
                if best_val is None or val > best_val:
                    best_val, best_idx = val, i
            selected.append(best_idx)
            remaining.remove(best_idx)
        return selected

    # -- retrieval ----------------------------------------------------------
    def retrieve(
        self,
        query: str,
        filters: Optional[Dict[str, Any]] = None,
        top_k: int = 5,
        weights: Optional[Dict[str, float]] = None,
        use_mmr: bool = False,
        mmr_lambda: float = 0.7,
        fetch_factor: int = 4,
    ) -> List[Dict[str, Any]]:
        """Retrieve, filter by metadata, hybrid-rank, boost, and (optionally)
        MMR-rerank chunks relevant to the query.

        Pipeline:
            all chunks -> metadata filter -> hybrid score (tfidf + bm25,
            min-max normalized, weighted) -> metadata boost multipliers ->
            rank -> diversity rerank -> top_k results.
        """
        self._ensure_index()
        top_k = max(1, int(top_k))
        weights = weights or {"tfidf": 0.5, "bm25": 0.5}
        if not self.chunks:
            return []

        query_tokens = tokenize(query)
        mfilter = MetadataFilter(filters)
        candidates = [
            i for i in range(len(self.chunks))
            if mfilter.matches(self.chunks[i]["metadata"])
        ]
        if not candidates:
            return []

        tf_scores = self.tfidf.score_all(query_tokens, candidates)
        bm_scores = self.bm25.score_all(query_tokens, candidates)
        tf_norm = self._minmax(tf_scores, candidates)
        bm_norm = self._minmax(bm_scores, candidates)

        fused: Dict[int, float] = {}
        for i in candidates:
            fused[i] = (
                weights.get("tfidf", 0.5) * tf_norm.get(i, 0.0)
                + weights.get("bm25", 0.5) * bm_norm.get(i, 0.0)
            )
        for i in candidates:
            boost = 1.0
            for booster in self.boosters:
                boost *= booster(self.chunks[i]["metadata"])
            fused[i] *= boost

        ranked = sorted(candidates, key=lambda i: fused[i], reverse=True)
        pool = ranked[: max(top_k * fetch_factor, top_k)]
        selected = self._mmr(pool, fused, mmr_lambda, top_k) if use_mmr else pool[:top_k]

        results: List[Dict[str, Any]] = []
        for i in selected:
            meta = self.chunks[i]["metadata"]
            results.append({
                "chunk_id": meta["chunk_id"],
                "doc_id": meta["doc_id"],
                "title": meta.get("title", ""),
                "text": self.chunks[i]["text"],
                "metadata": dict(meta),
                "score": round(fused[i], 6),
                "tfidf": round(tf_norm.get(i, 0.0), 6),
                "bm25": round(bm_norm.get(i, 0.0), 6),
            })
        return results

    # -- grounded answer generation (extractive, with citations) ------------
    def answer(self, query: str, results: List[Dict[str, Any]],
               max_sentences: int = 3) -> str:
        """Extract the most query-overlapping sentences from retrieved chunks
        and cite their source documents."""
        q_terms = set(tokenize(query))
        scored: List[Tuple[int, float, Dict[str, Any], str]] = []
        seen = set()
        for r in results:
            for sentence in SENTENCE_RE.split(r["text"]):
                sentence = sentence.strip()
                if len(sentence) < 20:
                    continue
                key = tuple(tokenize(sentence))
                if key in seen or not key:
                    continue
                seen.add(key)
                overlap = q_terms & set(key)
                if overlap:
                    scored.append((len(overlap), r["score"], r, sentence))
        scored.sort(key=lambda x: (x[0], x[1]), reverse=True)

        if not scored:
            return "No grounded answer could be extracted from the retrieved context."

        parts: List[str] = []
        cited: Dict[str, str] = {}  # doc_id -> title
        for _, _, r, sentence in scored[:max_sentences]:
            doc_id = r["metadata"]["doc_id"]
            if doc_id not in cited:
                cited[doc_id] = r["metadata"].get("title", doc_id)
            parts.append(sentence + f" [{doc_id}]")
        source_line = "Sources: " + "; ".join(
            f"{doc_id} ({title})" for doc_id, title in cited.items()
        )
        return " ".join(parts) + "\n" + source_line

    # -- evaluation ---------------------------------------------------------
    def evaluate(self, cases: List[Dict[str, Any]], top_k: int = 5):
        """Recall@k and MRR over expected doc_ids per test case."""
        report: List[Dict[str, Any]] = []
        for case in cases:
            results = self.retrieve(case["query"], case.get("filters"), top_k=top_k)
            retrieved = [r["metadata"]["doc_id"] for r in results]
            relevant = set(case.get("relevant", []))
            recall = len(relevant & set(retrieved)) / len(relevant) if relevant else 0.0
            mrr = 0.0
            for rank, doc_id in enumerate(retrieved, start=1):
                if doc_id in relevant:
                    mrr = 1.0 / rank
                    break
            report.append({
                "query": case["query"],
                "filters": case.get("filters", {}),
                "relevant": sorted(relevant),
                "retrieved": retrieved,
                "recall_at_k": round(recall, 3),
                "mrr": round(mrr, 3),
            })
        avg_recall = sum(x["recall_at_k"] for x in report) / len(report)
        avg_mrr = sum(x["mrr"] for x in report) / len(report)
        return report, {"avg_recall_at_k": round(avg_recall, 3), "avg_mrr": round(avg_mrr, 3)}


# ---------------------------------------------------------------------------
# Sample corpus: a fictional cloud platform's documentation
# ---------------------------------------------------------------------------

SAMPLE_DOCS = [
    {
        "doc_id": "doc-001", "title": "Getting Started with Apollo Cloud",
        "category": "onboarding", "author": "maya@example.com",
        "date": "2024-01-10", "source": "docs", "priority": "high",
        "tags": ["setup", "account", "cli"],
        "text": (
            "Welcome to Apollo Cloud. This guide walks you through your first "
            "project from account creation to deploying a hello world service.\n\n"
            "Create an account by visiting console.apollo.example and confirming "
            "your email address. Choose an organization name and a default region "
            "such as us-east-1 or eu-west-2.\n\n"
            "Install the Apollo CLI with pip install apollo-cli. Authenticate with "
            "apollo login and verify your identity with a short-lived verification "
            "code. The CLI stores credentials in the standard credential file.\n\n"
            "Initialize your first project with apollo init. This creates a "
            "project.toml manifest describing your services, environment variables, "
            "and resource limits.\n\n"
            "Deploy a sample service with apollo deploy. Watch the rollout progress "
            "in the dashboard. New deployments are automatically load balanced "
            "across availability zones in your chosen region."
        ),
    },
    {
        "doc_id": "doc-002", "title": "Apollo Projects and Workspaces",
        "category": "onboarding", "author": "juan@example.com",
        "date": "2024-02-14", "source": "docs", "priority": "medium",
        "tags": ["projects", "workspaces", "iam"],
        "text": (
            "Projects group related services, budgets, and access policies. Each "
            "project belongs to exactly one organization and one or more teams.\n\n"
            "Workspaces give every engineer an isolated environment with its own "
            "secrets, database instances, and deployment targets. Promote code "
            "between workspaces after automated checks pass.\n\n"
            "Workspace variables can reference project-level secrets without "
            "exposing their values in logs or diffs. Use the workspace selector in "
            "the CLI or dashboard to switch context.\n\n"
            "Deletion of a workspace is permanent. Export configuration first if "
            "you need an audit trail, because removed workspaces cannot be "
            "recovered from the recycle bin after thirty days."
        ),
    },
    {
        "doc_id": "doc-003", "title": "Network Configuration: VPC Peering and Private Links",
        "category": "network", "author": "priya@example.com",
        "date": "2024-03-01", "source": "docs", "priority": "high",
        "tags": ["vpc", "peering", "private-link", "latency"],
        "text": (
            "Connect Apollo workloads to your own infrastructure with VPC peering "
            "or AWS PrivateLink style private connections.\n\n"
            "VPC peering links two networks using non-overlapping CIDR ranges. "
            "Route tables must reference the peering connection explicitly; "
            "Apollo does not auto-propagate routes.\n\n"
            "Private links expose services over a private endpoint without "
            "traversing the public internet, which improves security and reduces "
            "inter-region latency.\n\n"
            "Use route analyzer to validate path symmetry before failover tests. "
