# Demo / validation
# ---------------------------------------------------------------------------

def fmt_results(results: List[Dict[str, Any]]) -> str:
    lines = []
    for r in results:
        snippet = re.sub(r"\s+", " ", r["text"])[:110]
        lines.append(
            f"  {r['score']:.4f}  {r['doc_id']:<9} [{r['metadata'].get('category')}"
            f" | {r['metadata'].get('date')} | priority={r['metadata'].get('priority')}]"
            f"\n           {snippet}..."
        )
    return "\n".join(lines)


def run_demo() -> None:
    system = MetadataAwareRAG(chunk_size=700, chunk_overlap=90)
    n_chunks = system.add_documents(SAMPLE_DOCS)
    system.build_index()

    print("=" * 78)
    print("METADATA-AWARE RAG SYSTEM — DEMO")
    print("=" * 78)
    print(f"Documents indexed : {len(SAMPLE_DOCS)}")
    print(f"Chunks indexed    : {n_chunks}")
    print(f"Vocabulary size   : {len(system.tfidf.idf)}")
    print(f"Boosters active   : "
          f"{[type(b).__name__ for b in system.boosters]}")
    print()

    demo_queries = [
        ("rotate API key", {"category": "security"},
         "Metadata filter restricts candidates to security docs."),
        ("object storage pricing per GB", {},
         "No filter: hybrid ranking surfaces pricing + storage docs."),
        ("object storage pricing per GB", {"category": "pricing"},
         "Metadata filter drops the storage doc; pricing docs win."),
        ("reduce network latency", {"priority": "high"},
         "Priority filter keeps only high-priority candidates."),
        ("billing discounts after June 2024", {"date": {"$gte": "2024-06-01"}},
         "Date-range filter; recency boost favors newer docs."),
    ]

    for query, filters, note in demo_queries:
        print("-" * 78)
        print(f"QUERY : {query!r}")
        print(f"FILTER: {filters}")
        print(f"NOTE  : {note}")
        results = system.retrieve(query, filters=filters, top_k=3, use_mmr=True)
        if not results:
            print("  (no candidates matched the metadata filter)")
        else:
            print(fmt_results(results))
        print()

    # -- metadata boost demonstration --------------------------------------
    print("-" * 78)
    print("METADATA BOOST DEMONSTRATION (query: 'rotate API key', "
          "filter: category=security, top_k=2)")
    query, filters = "rotate API key", {"category": "security"}
    default_boosters = system.boosters
    system.boosters = []
    no_boost = system.retrieve(query, filters=filters, top_k=2)
    system.boosters = default_boosters
    with_boost = system.retrieve(query, filters=filters, top_k=2)
    print("  Without boosters:")
    for r in no_boost:
        print(f"    {r['score']:.4f}  {r['doc_id']}  (priority={r['metadata']['priority']}, "
              f"date={r['metadata']['date']})")
    print("  With priority + recency boosters:")
    for r in with_boost:
        print(f"    {r['score']:.4f}  {r['doc_id']}  (priority={r['metadata']['priority']}, "
              f"date={r['metadata']['date']})")
    print()

    # -- grounded answer ----------------------------------------------------
    print("-" * 78)
    print("GROUNDED EXTRACTIVE ANSWER (query: 'object storage pricing')")
    results = system.retrieve("object storage pricing per GB", top_k=4)
    print(system.answer("object storage pricing per GB", results))
    print()

    # -- evaluation ---------------------------------------------------------
    print("-" * 78)
    print("EVALUATION (recall@5 and MRR over expected documents)")
    report, metrics = system.evaluate(EVAL_CASES, top_k=5)
    for row in report:
        print(f"  {row['query'][:45]:<47} recall@{5}={row['recall_at_k']}  "
              f"MRR={row['mrr']}  retrieved={row['retrieved']}")
    print(f"  {'AVERAGE':<47} recall@5={metrics['avg_recall_at_k']}  "
          f"MRR={metrics['avg_mrr']}")
    print("=" * 78)


if __name__ == "__main__":
    run_demo()
